// TypeScript Version: 4.1

/**
* Interface describing `dnthIndexOf`.
*/
interface Routine {
	/**
	* Returns the index of the n-th occurrence of a specified search element in a double-precision floating-point strided array.
	*
	* ## Notes
	*
	* -   If `N <= 0` or `k <= 0`, the function returns `-1`.
	* -   When searching for a search element, the function checks for equality using the strict equality operator `===`. As a consequence, `NaN` values are considered distinct, and `-0` and `+0` are considered the same.
	*
	* @param N - number of indexed elements
	* @param k - occurrence number. Must be a positive integer specifying which occurrence of the search element to find; `k=1` finds the first occurrence, `k=2` finds the second occurrence, and so on
	* @param searchElement - search element
	* @param x - input array
	* @param strideX - stride length
	* @returns index
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var x = new Float64Array( [ 1.0, 2.0, 3.0, 2.0 ] );
	*
	* var idx = dnthIndexOf( x.length, 2, 2.0, x, 1 );
	* // returns 3
	*/
	( N: number, k: number, searchElement: number, x: Float64Array, strideX: number ): number;

	/**
	* Returns the index of the n-th occurrence of a specified search element in a double-precision floating-point strided array using alternative indexing semantics.
	*
	* ## Notes
	*
	* -   If `N <= 0` or `k <= 0`, the function returns `-1`.
	* -   When searching for a search element, the function checks for equality using the strict equality operator `===`. As a consequence, `NaN` values are considered distinct, and `-0` and `+0` are considered the same.
	*
	* @param N - number of indexed elements
	* @param k - occurrence number. Must be a positive integer specifying which occurrence of the search element to find; `k=1` finds the first occurrence, `k=2` finds the second occurrence, and so on
	* @param searchElement - search element
	* @param x - input array
	* @param strideX - stride length
	* @param offsetX - starting index
	* @returns index
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var x = new Float64Array( [ 1.0, 2.0, 3.0, 2.0 ] );
	*
	* var idx = dnthIndexOf.ndarray( x.length, 2, 2.0, x, 1, 0 );
	* // returns 3
	*/
	ndarray( N: number, k: number, searchElement: number, x: Float64Array, strideX: number, offsetX: number ): number;
}

/**
* Returns the index of the n-th occurrence of a specified search element in a double-precision floating-point strided array.
*
* ## Notes
*
* -   If `N <= 0` or `k <= 0`, the function returns `-1`.
* -   When searching for a search element, the function checks for equality using the strict equality operator `===`. As a consequence, `NaN` values are considered distinct, and `-0` and `+0` are considered the same.
*
* @param N - number of indexed elements
* @param k - occurrence number
* @param searchElement - search element
* @param x - input array
* @param strideX - stride length
* @returns index
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var x = new Float64Array( [ 1.0, 2.0, 3.0, 2.0 ] );
*
* var idx = dnthIndexOf( x.length, 2, 2.0, x, 1 );
* // returns 3
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var x = new Float64Array( [ 1.0, 2.0, 3.0, 2.0 ] );
*
* var idx = dnthIndexOf.ndarray( x.length, 2, 2.0, x, 1, 0 );
* // returns 3
*/
declare var dnthIndexOf: Routine;


// EXPORTS //

export = dnthIndexOf;
